%% skyLuminanceBatch.m
% Created by Michael Wild, Version 06.05.2026
% michael.wild@zhaw.ch
%
% Function to obtain a sky luminance distribution from irradiation values
% and sun position using the Perez model.
% see:
% Perez et al., "All-Weather Model for Sky Luminance Distribution -
% Preliminary Configuration and Validation", Solar Energy 50, 1993.
%% Inputs
% 
% sky_elements  :   Cell Array of Sky Elements generated by hemispherePartition.m
% DNI           :   Direct Normal Irradiation [W/m^2]
% GHI           :   Global Horizontal Irradiation [W/m^2]
% DHI           :   Diffuse Horizontal Irradiation [W/m^2]
% sunposition   :   Struct containing .zenith and .azimuth [rad]
% zenithvec     :   Vector of zenith values of sky_elements [rad] (this is passed separately for speed reasons) 
%
%% Outputs
%
% lv            :   Luminosity Distribution on sky_elements [W/m^2/sr]
% gamma         :   Vector of angles between sun position and sky elements [rad] (reused later in the code)
%
function[lv,gamma] = skyLuminanceBatch(sky_elements, DNI, GHI, DHI, sunposition, zenithvec)


sunposition.elevation = pi/2 - sunposition.zenith;


Ees = DNI;                      % Normal incident direct irradiance
Direct_Horizontal = DNI*cos(sunposition.zenith);
Eed = GHI - Direct_Horizontal;  % Horizontal Diffuse
Eed = DHI;
Ees_0 = 1361;                   % Normal incident extraterrestrial irradiance

eps = ((Eed + Ees)/Eed + 1.041*sunposition.zenith^3)/(1+ 1.041*sunposition.zenith^3);
m = kasten(sunposition.elevation);
Delta = m*Eed/Ees_0;

a = [1.3525, -0.2576, -0.2690, -1.4366; ...
     -1.2219, -0.7730, 1.4148, 1.1016; ...
     -1.1000, -0.2515, 0.8952, 0.0156;...
     -0.5484, -0.6654, -0.2672, 0.7117;...
     -0.6000, -0.3566, -2.5000, 2.3250;...
     -1.0156, -0.3670, 1.0078, 1.4051; ...
     -1.0000, 0.0211, 0.5025, -0.5119; ...
     -1.0500, 0.0289, 0.4260, 0.3590];

b = [-0.7670, 0.0007, 1.2734, -1.233; ...
     -0.2054, 0.0367, -3.9128, 0.9156; ...
     0.2782, -0.1812, -4.5000, 1.1766;...
     0.7234, -0.6219, -5.6812, 2.6297;...
     0.2937, 0.0496, -5.6812, 1.8415; ... % yes, these coefficients are really exactly the same.
     0.2875, -0.5328, -3.8500, 3.3750; ...
     -0.3000, 0.1922, 0.7023, -1.6317; ...
     -0.3250, 0.1156, 0.7781, 0.0025];

c = [2.800, 0.6004, 1.2375, 1.000;...
    6.9750, 0.1774, 6.4477, -0.1239;...
    24.7219, -13.0812, -37.7000, 34.8438;...
    33.3389, -18.3000, -62.2500, 52.0781;...
    21.0000, -4.7656, -21.5906, 7.2492;...
    14.000, -0.9999, -7.1407, 7.5469;...
    19.0000, -5.000, 1.2438, -1.9094;...
    31.0625, -14.5000, -46.1148, 55.3750];

d = [1.8734, 0.6297, 0.9738, 0.2809;...
    -1.5798, -0.5081, -1.7812, 0.1080;...
    -5.000, 1.5218, 3.9229, -2.6204;...
    -3.500, 0.0016, 1.1477, 0.1062;...
    -3.500, -0.1554, 1.4062, 0.3988;...
    -3.400, -0.1078, -1.0750, 1.5702;...
    -4.000, 0.0250, 0.3844, 0.2652;...
    -7.2312, 0.4050, 13.3500, 0.6234];

e = [0.0356, -0.1246, -0.5718, 0.9938;...
    0.2624, 0.0672, -0.2190, -0.4285;...
    -0.0156, 0.1597, 0.4199, -0.5562;...
    0.4659, -0.3296, -0.0876, -0.0329;...
    0.0032, 0.0766, -0.0656, -0.1294;...
    -0.0672, 0.4016, 0.3017, -0.4844;...
    1.0468, -0.3788, -2.4517, 1.4656;...
    1.5, -0.6426, 1.8564, 0.5636];

eps_ranges = [1, 1.065, 1.230, 1.5, 1.95, 2.8, 4.5, 6.2];

eps_choice = max(1,min(8,sum(eps > eps_ranges)));


a_val = a(eps_choice, 1) + a(eps_choice,2)*sunposition.zenith + Delta*(a(eps_choice,3)+ a(eps_choice,4)*sunposition.zenith);
b_val = b(eps_choice, 1) + b(eps_choice,2)*sunposition.zenith + Delta*(b(eps_choice,3)+ b(eps_choice,4)*sunposition.zenith);
c_val = c(eps_choice, 1) + c(eps_choice,2)*sunposition.zenith + Delta*(c(eps_choice,3)+ c(eps_choice,4)*sunposition.zenith);
d_val = d(eps_choice, 1) + d(eps_choice,2)*sunposition.zenith + Delta*(d(eps_choice,3)+ d(eps_choice,4)*sunposition.zenith);
e_val = e(eps_choice, 1) + e(eps_choice,2)*sunposition.zenith + Delta*(e(eps_choice,3)+ e(eps_choice,4)*sunposition.zenith);

if (eps_choice == 1)
    c_val = exp(Delta*(c(1,1)+c(1,2)*sunposition.zenith)^c(1,3))-1;
    d_val = -exp(Delta*(d(1,1)+d(1,2)*sunposition.zenith))+d(1,3)+Delta*d(1,4);
end

[sunpos(1), sunpos(2), sunpos(3)] = sph2cart(sunposition.azimuth, sunposition.elevation, 1);
        sunpos(1) = -sin(sunposition.azimuth)*cos(sunposition.elevation);
        sunpos(2) = -cos(sunposition.azimuth)*cos(sunposition.elevation);
        sunpos(3) = sin(sunposition.elevation);

for i = 1:length(sky_elements)
    gamma(i) = acos(dot(sunpos,sky_elements{i}.pos));
end
lv = (1 + a_val * exp(b_val./cos(zenithvec))).*(1+ c_val * exp(d_val*gamma) + e_val*cos(gamma).^2);
